    }
    link.focus();
  });
  list.keydown(function(e) {
    var selected = $(this).find('li a:focus');
    if (e.keyCode === 27) { // Esc key
      isOpen = false;
      list.slideUp(200);
      link.focus();
    } else if (e.keyCode === 38) { // Up arrow
