```typescript
// auth/auth.service.ts
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Token } from './entities/token.entity';
import { User } from './entities/user.entity';
import * as argon2 from 'argon2';
import * as jwt from 'jsonwebtoken';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private userRepository: Repository<User>,
    @InjectRepository(Token)
    private tokenRepository: Repository<Token>,
  ) {}

  async validateUser(username: string, password: string): Promise<User | null> {
    const user = await this.userRepository.findOne({ where: { username } });

    if (!user) {
      return null;
    }

    const passwordValid = await argon2.verify(user.passwordHash, password);

    if (!passwordValid) {
      return null;
    }

    return user;
  }

  async generateTokens(user: User): Promise<Token> {
    const accessToken = jwt.sign(
      { userId: user.id },
      'your_access_token_secret',
      { expiresIn: '15m' },
    );

    const refreshToken = jwt.sign(
      { userId: user.id },
      'your_refresh_token_secret',
      { expiresIn: '7d' },
    );

    const token = new Token();
    token.userId = user.id;
    token.accessToken = accessToken;
    token.refreshToken = refreshToken;

    await this.tokenRepository.save(token);

    return token;
  }

  async refreshTokens(refreshToken: string): Promise<Token | null> {
    try {
      const refreshPayload = jwt.verify(
        refreshToken,
        'your_refresh_token_secret',
      ) as { userId: number };

      const token = await this.tokenRepository.findOne({
        where: { refreshToken, userId: refreshPayload.userId },
      });

      if (!token) {
        return null;
      }

      jwt.verify(token.accessToken, 'your_access_token_secret');

      const newAccessToken = jwt.sign(
        { userId: token.userId },
        'your_access_token_secret',
        { expiresIn: '15m' },
      );

      token.accessToken = newAccessToken;
      await this.tokenRepository.save(token);

      return token;
    } catch (error) {
      return null;
    }
  }

  async getUserFromAccessToken(accessToken: string): Promise<User | null> {
    try {
      const payload = jwt.verify(
        accessToken,
        'your_access_token_secret',
      ) as { userId: number };

      const user = await this.userRepository.findOne(payload.userId);

      if (!user) {
        return null;
      }

      return user;
    } catch (error) {
      return null;
    }
  }
}
```

Now, let's create the `AuthResolver` to handle the GraphQL authentication queries and mutations:

```typescript
// auth/auth.resolver.ts
import { Args, Mutation, Resolver } from '@nestjs/graphql';
import { AuthService } from './auth.service';
import { User } from './entities/user.entity';

@Resolver()
export class AuthResolver {
  constructor(private authService: AuthService) {}

  @Mutation(() => User)
  async login(
    @Args('username') username: string,
    @Args('password') password: string,
  ): Promise<User | null> {
    const user = await this.authService.validateUser(username, password);

    if (!user) {
      return null;
    }

    return user;
  }

  @Mutation(() => User)
  async refreshTokens(
    @Args('refreshToken') refreshToken: string,
  ): Promise<User | null> {
    const token = await this.authService.refreshTokens(refreshToken);

    if (!token) {
      return null;
    }

    const user = await this.authService.getUserFromAccessToken(token.accessToken);

    if (!user) {
      return null;
    }

    return user;
  }
}
```

Next, create the `AuthGuard` and `JwtStrategy` classes to handle the authentication guards and JWT strategy for protecting GraphQL resolvers:

