Below is a basic C# script that spawns an object within a defined area:

```csharp
using UnityEngine;

public class Spawner : MonoBehaviour
{
    public GameObject objectToSpawn; // Drag the prefab you want to spawn into this field in the inspector.
    public Vector2 areaTopLeft;      // Set the top left corner of the spawn area.
    public Vector2 areaBottomRight;  // Set the bottom right corner of the spawn area.

    private void Start() 
    {
        SpawnObjectInArea();
    }

    private void SpawnObjectInArea()
    {
