            // Calculate a random position within the defined area.
            float spawnPosX = Random.Range(areaTopLeft.x, areaBottomRight.x);
            float spawnPosY = Random.Range(areaBottomRight.y, areaTopLeft.y);

            // Since C# in Unity uses float for vectors, we cast to Vector3 to be used in Instantiate.
