3. **Web Server Code**: The ESP32 should serve a web page that displays the camera footage and includes buttons to control the door and light. Use the ESPAsyncWebServer library for a more efficient server.

```cpp
#include "ESPAsyncWebServer.h"
#include "SPIFFS.h"

AsyncWebServer server(80);

void setup() {
  // ... previous setup code ...

  if (!SPIFFS.begin(true)) {
    Serial.println("An Error has occurred while mounting SPIFFS");
    return;
  }

  server.on("/", HTTP_GET, [](AsyncWebServerRequest *request) {
    request->send(SPIFFS, "/index.html", "text/html");
  });

  server.on("/open-door", HTTP_GET, [](AsyncWebServerRequest *request) {
    // Code to open the door
    // For example, if using a relay on pin 12:
    digitalWrite(12, HIGH);
    delay(1000); // keep the door open for 1 second
    digitalWrite(12, LOW);
    request->send(200, "text/plain", "Door opened!");
  });

  server.on("/toggle-light", HTTP_GET, [](AsyncWebServerRequest *request) {
    // Code to toggle the light
    // For example, if using an LED on pin 13:
    bool lightState = digitalRead(13);
    digitalWrite(13, !lightState);
    request->send(200, "text/plain", lightState ? "Light Off" : "Light On");
  });

  // Serve the camera feed as a stream
  server.on("/camera", HTTP_GET, [](AsyncWebServerRequest *request) {
    request->send(200, "multipart/x-mixed-replace; boundary=--frameboundary", "");
  });

  // Start server
  server.begin();
}

void loop() {
  // Handle server activities
}
