public static String swapEnds(String a) {
    // Check if the string has at least 2 characters
    if (a.length() < 2) {
        return a; // Return the original string as is
    }

    // Get the first and last characters of the string
    char first = a.charAt(0);
    char last = a.charAt(a.length() - 1);

